window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b3111859d5e0ed1b"]={"versions": [{"id": "FIG-b3111859d5e0ed1b", "releases": ["R3.2.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Konfigurationsübersicht für die AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library), speziell zur E2E-Profil-Konfiguration bezüglich <code>DataIDList</code> bei Profile 2. Das Schaubild veranschaulicht eine unzulässige Konfiguration („forbidden configuration“) der Zuordnung von Data-IDs zum E2E-Counter auf Empfängerseite (<code>Receiver-ECU</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Receiver-ECU</code>: Empfänger-Steuergerät bzw. E2E-Instanz auf Empfängerseite.\n</li><li><code>message</code>: Bezeichner für den empfangenen Nachrichtenstrom <code>G</code>.\n</li><li><code>Counter =</code>: Wertebereich des 4-Bit-Zählers von <code>0</code> bis <code>15</code>.\n</li><li><code>DataIDList</code>: Konfigurationsarray mit 16 Werten für den Empfänger <code>G</code>:\n<ul class=\"fig-list\"><li>Counter 0: <code>73</code>\n</li><li>Counter 1: <code>144</code>\n</li><li>Counter 2: <code>215</code>\n</li><li>Counter 3: <code>35</code>\n</li><li>Counter 4: <code>106</code>\n</li><li>Counter 5: <code>177</code>\n</li><li>Counter 6: <code>248</code>\n</li><li>Counter 7: <code>68</code>\n</li><li>Counter 8: <code>139</code>\n</li><li>Counter 9: <code>210</code>\n</li><li>Counter 10: <code>30</code>\n</li><li>Counter 11: <code>101</code>\n</li><li>Counter 12: <code>172</code>\n</li><li>Counter 13: <code>243</code>\n</li><li>Counter 14: <code>63</code>\n</li><li>Counter 15: <code>134</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Tabelle stellt die statische Zuordnung dar, anhand derer bei E2E Profile 2 pro Zählerstand (<code>Counter</code> von 0 bis 15) die erwartete 8-Bit-Teil-ID aus <code>DataIDList</code> für die CRC-Berechnung und Integritätsprüfung herangezogen wird. Bei jedem Inkrement des 4-Bit-Counters adressiert die E2E-Prüfroutine das entsprechende Element im Array (z. B. Index 0 → 73, Index 1 → 144 bis Index 15 → 134).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die dargestellte Konfiguration ist normativ als unzulässig („forbidden configuration“) eingestuft. Integratoren und E2E-Entwickler müssen sicherstellen, dass <code>DataIDList</code> nicht mit dem gezeigten Sequenzmuster konfiguriert wird, um Schutzlücken bzw. Kollisionen bei der E2E-Validierung von Botschaften zu vermeiden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fedc0cae049cdb56", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Konfigurationsübersicht für die AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library), speziell zur E2E-Profil-Konfiguration bezüglich <code>DataIDList</code> bei Profile 2. Das Schaubild veranschaulicht eine unzulässige Konfiguration („forbidden configuration“) der Zuordnung von Data-IDs zum E2E-Counter auf Empfängerseite (<code>Receiver-ECU</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Receiver-ECU</code>: Empfänger-Steuergerät bzw. E2E-Instanz auf Empfängerseite.\n</li><li><code>message</code>: Bezeichner für den empfangenen Nachrichtenstrom <code>G</code>.\n</li><li><code>Counter =</code>: Wertebereich des 4-Bit-Zählers von <code>0</code> bis <code>15</code>.\n</li><li><code>DataIDList</code>: Konfigurationsarray mit 16 Werten für den Empfänger <code>G</code>:\n<ul class=\"fig-list\"><li>Counter 0: <code>73</code>\n</li><li>Counter 1: <code>144</code>\n</li><li>Counter 2: <code>215</code>\n</li><li>Counter 3: <code>35</code>\n</li><li>Counter 4: <code>106</code>\n</li><li>Counter 5: <code>177</code>\n</li><li>Counter 6: <code>248</code>\n</li><li>Counter 7: <code>68</code>\n</li><li>Counter 8: <code>139</code>\n</li><li>Counter 9: <code>210</code>\n</li><li>Counter 10: <code>30</code>\n</li><li>Counter 11: <code>101</code>\n</li><li>Counter 12: <code>172</code>\n</li><li>Counter 13: <code>243</code>\n</li><li>Counter 14: <code>63</code>\n</li><li>Counter 15: <code>134</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Tabelle stellt die statische Zuordnung dar, anhand derer bei E2E Profile 2 pro Zählerstand (<code>Counter</code> von 0 bis 15) die erwartete 8-Bit-Teil-ID aus <code>DataIDList</code> für die CRC-Berechnung und Integritätsprüfung herangezogen wird. Bei jedem Inkrement des 4-Bit-Counters adressiert die E2E-Prüfroutine das entsprechende Element im Array (z. B. Index 0 → 73, Index 1 → 144 bis Index 15 → 134).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die dargestellte Konfiguration ist normativ als unzulässig („forbidden configuration“) eingestuft. Integratoren und E2E-Entwickler müssen sicherstellen, dass <code>DataIDList</code> nicht mit dem gezeigten Sequenzmuster konfiguriert wird, um Schutzlücken bzw. Kollisionen bei der E2E-Validierung von Botschaften zu vermeiden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ad5fea3fdb0272e2", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Konfigurationsübersicht für die AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library), speziell zur E2E-Profil-Konfiguration bezüglich <code>DataIDList</code> bei Profile 2. Das Schaubild veranschaulicht eine unzulässige Konfiguration („forbidden configuration“) der Zuordnung von Data-IDs zum E2E-Counter auf Empfängerseite (<code>Receiver-ECU</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Receiver-ECU</code>: Empfänger-Steuergerät bzw. E2E-Instanz auf Empfängerseite.\n</li><li><code>message</code>: Bezeichner für den empfangenen Nachrichtenstrom <code>G</code>.\n</li><li><code>Counter =</code>: Wertebereich des 4-Bit-Zählers von <code>0</code> bis <code>15</code>.\n</li><li><code>DataIDList</code>: Konfigurationsarray mit 16 Werten für den Empfänger <code>G</code>:\n<ul class=\"fig-list\"><li>Counter 0: <code>73</code>\n</li><li>Counter 1: <code>144</code>\n</li><li>Counter 2: <code>215</code>\n</li><li>Counter 3: <code>35</code>\n</li><li>Counter 4: <code>106</code>\n</li><li>Counter 5: <code>177</code>\n</li><li>Counter 6: <code>248</code>\n</li><li>Counter 7: <code>68</code>\n</li><li>Counter 8: <code>139</code>\n</li><li>Counter 9: <code>210</code>\n</li><li>Counter 10: <code>30</code>\n</li><li>Counter 11: <code>101</code>\n</li><li>Counter 12: <code>172</code>\n</li><li>Counter 13: <code>243</code>\n</li><li>Counter 14: <code>63</code>\n</li><li>Counter 15: <code>134</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Tabelle stellt die statische Zuordnung dar, anhand derer bei E2E Profile 2 pro Zählerstand (<code>Counter</code> von 0 bis 15) die erwartete 8-Bit-Teil-ID aus <code>DataIDList</code> für die CRC-Berechnung und Integritätsprüfung herangezogen wird. Bei jedem Inkrement des 4-Bit-Counters adressiert die E2E-Prüfroutine das entsprechende Element im Array (z. B. Index 0 → 73, Index 1 → 144 bis Index 15 → 134).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die dargestellte Konfiguration ist normativ als unzulässig („forbidden configuration“) eingestuft. Integratoren und E2E-Entwickler müssen sicherstellen, dass <code>DataIDList</code> nicht mit dem gezeigten Sequenzmuster konfiguriert wird, um Schutzlücken bzw. Kollisionen bei der E2E-Validierung von Botschaften zu vermeiden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b3111859d5e0ed1b", "to": "FIG-fedc0cae049cdb56", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fedc0cae049cdb56", "to": "FIG-b3111859d5e0ed1b", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b3111859d5e0ed1b", "to": "FIG-ad5fea3fdb0272e2", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
